36	/** Works out a sheet's figures the way the screen shows them (claimed, due-total, overdue-total, and their totals). */
37	@Service
38	public class Rollup {
39	
40	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
41	
42	    private final People people;
43	    private final Claims claims;
44	    private final Rates rates;
45	    private final Sheets sheets;
46	    private final Settings settings;
47	
48	    public Rollup(People people, Claims claims, Rates rates, Sheets sheets, Settings settings) {
49	        this.people = people;
50	        this.claims = claims;
51	        this.rates = rates;
52	        this.sheets = sheets;
53	        this.settings = settings;
54	    }
55	
56	    public Figures figures(String sheetId) {
57	        LocalDate today = sheets.today(sheetId);
58	        List<Claim> counting = claims.list(sheetId).stream()
59	                .filter(c -> c.status().counts()).toList();
60	        Map<Long, Figures.PersonFigures> figures = new LinkedHashMap<>();
61	        BigDecimal claimedTotal = ZERO;
62	        BigDecimal dueTotal = ZERO;
63	        BigDecimal overdueTotal = ZERO;
64	        for (Person person : people.list(sheetId)) {
65	            BigDecimal claimed = ZERO;
66	            BigDecimal due = ZERO;
67	            BigDecimal overdue = ZERO;
68	            boolean anyFigure = false;
69	            for (Claim claim : counting) {
70	                if (claim.personId() != person.id() || !counts(claim, person, today)) {
71	                    continue;
72	                }
73	                claimed = claimed.add(claim.amount());
74	                BigDecimal figure = figure(claim, person, today);
75	                if (figure != null) {
76	                    due = due.add(figure);
77	                    anyFigure = true;
78	                    if (overdue(claim, today)) {
79	                        overdue = overdue.add(figure);
80	                    }
81	                }
82	            }
83	            // With no rate today and no figure, the due-total is n/a.
84	            boolean none = !anyFigure && rates.on(sheetId, person.gradeOn(today), today) == null;
85	            // Otherwise it is held to the sheet's cap.
86	            due = settings.capped(sheetId, due);
87	            claimedTotal = claimedTotal.add(claimed);
88	            if (!none) {
89	                dueTotal = dueTotal.add(due);
90	            }
91	            overdueTotal = overdueTotal.add(overdue);
92	            figures.put(person.id(), new Figures.PersonFigures(person.name(), claimed.toPlainString(),
93	                    none ? "n/a" : due.toPlainString(), overdue.toPlainString()));
94	        }
95	        return new Figures(figures, claimedTotal.toPlainString(), dueTotal.toPlainString(),
96	                overdueTotal.toPlainString());
97	    }
98	
99	    /** An open (OPEN or PENDING) claim, not deferred, whose due-by (fixed when it was made) is before {@code today}. */
100	    private static boolean overdue(Claim claim, LocalDate today) {
101	        return claim.status().isOpen() && !claim.deferredOn(today) && claim.dueBy() != null && today != null && claim.dueBy().isBefore(today);
102	    }
103	
104	    /**
105	     * Each person's due-total for the dates {@code from} to {@code to} inclusive, by person id in sheet order: the
106	     * figures of their counting claims dated then, those without one skipped.
107	     */
108	    public Map<Long, BigDecimal> personDueTotals(String sheetId, LocalDate from, LocalDate to) {
109	        LocalDate today = sheets.today(sheetId);
110	        List<Claim> dated = claims.list(sheetId).stream().filter(c -> c.status().counts()
111	                && !c.date().isBefore(from) && !c.date().isAfter(to)).toList();
112	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
113	        for (Person person : people.list(sheetId)) {
114	            BigDecimal total = ZERO;
115	            for (Claim claim : dated) {
116	                if (claim.personId() != person.id() || !counts(claim, person, today)) {
117	                    continue;
118	                }
119	                BigDecimal figure = figure(claim, person, today);
120	                if (figure != null) {
121	                    total = total.add(figure);
122	                }
123	            }
124	            totals.put(person.id(), total);
125	        }
126	        return totals;
127	    }
128	
129	    /** The claim's figure as the screen shows it on the sheet's today (null: n/a), whatever its status. */
130	    public BigDecimal figure(Claim claim) {
131	        Person person = people.find(claim.sheetId(), claim.personId());
132	        return person == null ? claim.settledDue() : figure(claim, person, sheets.today(claim.sheetId()));
133	    }
134	
135	    /**
136	     * Whether the (OPEN, PENDING or SETTLED) claim counts: a person's open claims dated within one of their holds
137	     * count in no live total, unless a statement bound them; nor does an OPEN claim deferred on {@code today}.
138	     */
139	    public static boolean counts(Claim claim, Person person, LocalDate today) {
140	        if (claim.deferredOn(today)) {
141	            return false;
142	        }
143	        boolean bound = claim.stated() && claim.status() != ClaimStatus.PENDING;
144	        return !(claim.status().isOpen() && !bound && person.heldOn(claim.date()));
145	    }
146	
147	    /**
148	     * The claim's figure (null when it has none): a settled claim's frozen due, otherwise the figure its person's
149	     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, rounded by the policy date, raised to the floor;
150	     * an overdue claim's late charge on {@code today} added on top of the last two.
151	     */
152	    private BigDecimal figure(Claim claim, Person person, LocalDate today) {
153	        if (claim.settledDue() != null) {
154	            return claim.settledDue();
155	        }
156	        return settings.withLate(claim, bound(claim, person), today);
157	    }
158	
159	    /**
160	     * The claim's figure before any late charge: the one its person's last statement bound, else its floored live figure.
161	     * A PENDING claim is not bound: it shows its live figure until approved or rejected.
162	     */
163	    private BigDecimal bound(Claim claim, Person person) {
164	        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
165	            return claim.statedDue();
166	        }
167	        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
168	        return settings.live(claim, rate);
169	    }
170	}
