449	/**
450	 * Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID. A clerk's
451	 * settle of a claim whose due is above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED)
452	 * or rejects it (back to OPEN).
453	 */
454	public enum ClaimStatus {
455	    DRAFT, OPEN, PENDING, SETTLED, VOID;
456	
457	    /** Whether a claim in this status may move to {@code next}. */
458	    public boolean allows(ClaimStatus next) {
459	        return switch (next) {
460	            case OPEN -> this == DRAFT || this == PENDING;
461	            case PENDING -> this == OPEN;
462	            case SETTLED -> this == OPEN || this == PENDING;
463	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
464	            case DRAFT -> false;
465	        };
466	    }
467	
468	    /** Whether a claim in this status is open: OPEN, or PENDING, which is handled like OPEN in every total. */
469	    public boolean isOpen() {
470	        return this == OPEN || this == PENDING;
471	    }
472	
473	    /** Whether a claim in this status counts toward the totals: an open or a SETTLED one. */
474	    public boolean counts() {
475	        return isOpen() || this == SETTLED;
476	    }
477	
478	    /** The audit event of a change from {@code from} to this status. */
479	    public String event(ClaimStatus from) {
480	        if (from == PENDING) {
481	            return this == SETTLED ? "CLAIM_APPROVED" : this == OPEN ? "CLAIM_REJECTED" : event();
482	        }
483	        return event();
484	    }
485	
486	    /** The audit event of a change to this status. */
487	    public String event() {
488	        return switch (this) {
489	            case OPEN -> "CLAIM_OPENED";
490	            case PENDING -> "CLAIM_PENDING";
491	            case SETTLED -> "CLAIM_SETTLED";
492	            case VOID -> "CLAIM_VOIDED";
493	            case DRAFT -> "CLAIM_DRAFTED";
494	        };
495	    }
