498	package net.officefloor.hq.app.claim;
499	
500	
501	public class ApplyClaimStatus {
502	    // Stored only if the claim still has the status it was loaded with, so two users cannot both move it.
503	    // A PENDING claim moves only by a steward's decision: "approve" (to SETTLED) or "reject" (to OPEN, with a reason);
504	    // a decision is refused for any claim not PENDING. A PENDING claim can also be voided, like an OPEN one.
505	    public void apply(@PathVariable("status") String status, @RequestBody(required = false) ClaimStatusRequest body,
506	            @Val Claim claim, Claims claims, People people, Rates rates, Settings settings, Sheets sheets,
507	            Periods periods, Rollup rollup, ServerHttpConnection connection, Out<ClaimResponse> responseOut,
508	            Out<ClaimStatusRequest> requestOut) throws ClaimStatusRefusedException {
509	        ClaimStatus next;
510	        try {
511	            next = ClaimStatus.valueOf(status.trim().toUpperCase());
512	        } catch (IllegalArgumentException e) {
513	            throw new ClaimStatusRefusedException("Not a claim status: " + status);
514	        }
515	        String user = Audit.user(connection).trim();
516	        String action = body == null || body.action() == null ? "" : body.action().trim();
517	        String reason = body == null || body.reason() == null ? "" : body.reason().trim();
518	        boolean decision = !action.isEmpty();
519	        if (decision && !(action.equals("approve") && next == ClaimStatus.SETTLED)
520	                && !(action.equals("reject") && next == ClaimStatus.OPEN)) {
521	            throw new ClaimStatusRefusedException("Not a decision on a pending claim: " + action);
522	        }
523	        if (decision && claim.status() != ClaimStatus.PENDING) {
524	            throw new ClaimStatusRefusedException("Only a PENDING claim is approved or rejected.");
525	        }
526	        if (!decision && claim.status() == ClaimStatus.PENDING && next != ClaimStatus.VOID) {
527	            throw new ClaimStatusRefusedException("A PENDING claim is approved or rejected by a steward, or voided.");
528	        }
529	        boolean steward = Settings.STEWARD.equals(settings.role(claim.sheetId(), user));
530	        if (next == ClaimStatus.PENDING) {
531	            throw new ClaimStatusRefusedException("A claim becomes PENDING only when a clerk settles it above the clerk limit.");
532	        }
533	        // Four eyes: the user who opened a claim cannot settle it, nor approve it.
534	        if (next == ClaimStatus.SETTLED && claim.openedBy() != null && claim.openedBy().equals(user)) {
535	            throw new ClaimStatusRefusedException(claim.status() == ClaimStatus.PENDING
536	                    ? "The user who opened a claim cannot approve it."
537	                    : "The user who opened a claim cannot settle it.");
538	        }
539	        // A deferred claim cannot be settled until the sheet's today reaches its deferred-until date.
540	        if (next == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(claim.sheetId()))) {
541	            throw new ClaimStatusRefusedException("The claim is deferred until " + claim.deferredUntil() + ": it cannot be settled yet.");
542	        }
543	        if (!claim.status().allows(next)) {
544	            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
545	        }
546	        if (claim.status() == ClaimStatus.PENDING && (next == ClaimStatus.SETTLED || next == ClaimStatus.OPEN)
547	                && !steward) {
548	            throw new ClaimStatusRefusedException("Only a steward can approve or reject a pending claim.");
549	        }
550	        if (claim.status() == ClaimStatus.PENDING && next == ClaimStatus.OPEN && reason.isEmpty()) {
551	            throw new ClaimStatusRefusedException("Give a reason to reject the claim.");
552	        }
553	        // Settling (or approving) freezes the late charge on the sheet's today into the due.
554	        BigDecimal due = settings.withLate(claim, due(claim, people, rates, settings), sheets.today(claim.sheetId()));
555	        // A clerk settles only a claim whose due is at or below the clerk limit (a due of n/a is within any
556	        // limit); above it the claim goes PENDING, for a steward to approve. A steward settles anything.
557	        if (next == ClaimStatus.SETTLED && claim.status() == ClaimStatus.OPEN && due != null && !steward) {
558	            BigDecimal limit = settings.clerkLimit(claim.sheetId());
559	            if (limit != null && due.compareTo(limit) > 0) {
560	                next = ClaimStatus.PENDING;
561	            }
562	        }
563	        // While the sheet numbers by period (its today on or after the from-date), an opened claim is numbered
564	        // within the period its date falls in, or in the no-period sequence; otherwise sheet-wide.
565	        String scope = null;
566	        LocalDate numberingFrom = settings.periodNumberingFrom(claim.sheetId());
567	        if (next == ClaimStatus.OPEN && numberingFrom != null && !sheets.today(claim.sheetId()).isBefore(numberingFrom)) {
568	            Period period = periods.on(claim.sheetId(), claim.date());
569	            scope = period == null ? "" : period.name();
570	        }
571	        Claim changed = claims.changeStatus(claim, next, due, user, scope);
572	        if (changed == null) {
573	            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
574	        }
575	        claims.log(changed, user, sheets.today(claim.sheetId()), rollup.figure(changed));
576	        responseOut.set(ClaimResponse.from(changed));
577	        requestOut.set(new ClaimStatusRequest(action, reason));
578	    }
579	
580	    /**
581	     * The claim's due now, before its late charge: the figure its person's last statement bound it to (a PENDING
582	     * claim is not bound: its figure is live), otherwise its amount times its
583	     * person's grade's rate on the claim's date, rounded by the policy date, raised to the floor; null when none applies.
584	     */
585	    private static BigDecimal due(Claim claim, People people, Rates rates, Settings settings) {
586	        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
587	            return claim.statedDue();
588	        }
589	        Person person = people.find(claim.sheetId(), claim.personId());
590	        if (person == null) {
591	            return null;
592	        }
593	        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
594	        return settings.live(claim, rate);
595	    }
596	}
