2	/** The store of a sheet's settings and of the roles it gives user names, kept per sheet. */
3	@Repository
4	public class Settings {
5	    public static final String CLERK_LIMIT = "clerk-limit";
6	    public static final String FLOOR = "floor";
7	    public static final String FLOOR_DEFAULT = "1.00";
8	    public static final String TERMS = "terms";
9	    public static final String TERMS_DEFAULT = "14";
10	    /** The grades a sheet may give terms of their own, each kept under {@link #gradeTermsKey}. */
11	    public static final List<String> GRADES = List.of("A", "B", "C");
12	    public static final String LATE_PCT = "late-pct";
13	    public static final String LATE_PCT_DEFAULT = "0.00";
14	    public static final String POLICY_DATE = "policy-date";
15	    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";
16	    public static final String CAP = "cap";
17	    /** The settings that carry a figure: each value is kept from a from-date (see {@link #on}). */
18	    public static final List<String> DATED = List.of(CLERK_LIMIT, FLOOR, TERMS, gradeTermsKey("A"), gradeTermsKey("B"),
19	            gradeTermsKey("C"), LATE_PCT, CAP);
20	    public static final String CLERK = "clerk";
21	    public static final String STEWARD = "steward";
22	    private final JdbcTemplate jdbc;
23	    private final Sheets sheets;
24	    private final Claims claims;
25	    public Settings(JdbcTemplate jdbc, Sheets sheets, Claims claims) {
26	        this.jdbc = jdbc;
27	        this.sheets = sheets;
28	        this.claims = claims;
29	    }
30	    /** The setting's value; "" when it was never set. */
31	    public String get(String sheetId, String key) {
32	        List<String> values = jdbc.queryForList("SELECT setting_value FROM setting WHERE sheet_id = ? AND setting_key = ?",
33	                String.class, sheetId, key);
34	        return values.isEmpty() ? "" : values.get(0);
35	    }
36	    public void set(String sheetId, String key, String value) {
37	        jdbc.update("MERGE INTO setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key) VALUES (?, ?, ?)",
38	                sheetId, key, value);
39	    }
40	    /** A dated setting's value from a from-date; one already recorded from that date is replaced. */
41	    public void set(String sheetId, String key, LocalDate from, String value) {
42	        jdbc.update("MERGE INTO setting_from (sheet_id, setting_key, from_date, setting_value) KEY (sheet_id, setting_key, from_date)"
43	                + " VALUES (?, ?, ?, ?)", sheetId, key, java.sql.Date.valueOf(from), value);
44	    }
45	    /** A dated setting's value in force on the date: the one with the latest from-date on or before it; "" when there is none. */
46	    public String on(String sheetId, String key, LocalDate date) {
47	        List<String> values = jdbc.queryForList("SELECT setting_value FROM setting_from WHERE sheet_id = ? AND setting_key = ?"
48	                + " AND from_date <= ? ORDER BY from_date DESC LIMIT 1", String.class, sheetId, key, java.sql.Date.valueOf(date));
49	        return values.isEmpty() ? "" : values.get(0);
50	    }
51	    /** A dated setting's values, by from-date. */
52	    public List<DatedValue> history(String sheetId, String key) {
53	        return jdbc.query("SELECT from_date, setting_value FROM setting_from WHERE sheet_id = ? AND setting_key = ? ORDER BY from_date",
54	                (rs, n) -> new DatedValue(rs.getDate("from_date").toLocalDate().toString(), rs.getString("setting_value")),
55	                sheetId, key);
56	    }
57	    /** A dated setting's value from a from-date (yyyy-MM-dd). */
58	    public record DatedValue(String from, String value) {
59	    }
60	    /** A dated setting's value in force on the sheet's today; "" when there is none. */
61	    public String current(String sheetId, String key) {
62	        return on(sheetId, key, sheets.today(sheetId));
63	    }
64	    /** The clerk limit in force on the sheet's today; null when there is none. */
65	    public BigDecimal clerkLimit(String sheetId) {
66	        String value = current(sheetId, CLERK_LIMIT);
67	        return value.isEmpty() ? null : new BigDecimal(value);
68	    }
69	    /** The cap in force on the sheet's today, with two decimals: what a person's due-total is at most; null when there is none. */
70	    public BigDecimal cap(String sheetId) {
71	        String value = current(sheetId, CAP);
72	        return value.isEmpty() ? null : new BigDecimal(value);
73	    }
74	    /** A person's due-total held to the sheet's cap; null (n/a) stays null. */
75	    public BigDecimal capped(String sheetId, BigDecimal dueTotal) {
76	        BigDecimal cap = cap(sheetId);
77	        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
78	    }
79	    /** The floor in force on the date, with two decimals: what a claim's live due is at least; 1.00 when none is. */
80	    public BigDecimal floor(String sheetId, LocalDate date) {
81	        String value = on(sheetId, FLOOR, date);
82	        return new BigDecimal(value.isEmpty() ? FLOOR_DEFAULT : value);
83	    }
84	    /** The terms in force on the date: the number of days after its date a claim is due by; 14 when none are. */
85	    public int terms(String sheetId, LocalDate date) {
86	        String value = on(sheetId, TERMS, date);
87	        return Integer.parseInt(value.isEmpty() ? TERMS_DEFAULT : value);
88	    }
89	    /** The key a grade's own terms are kept under: terms-<grade>. */
90	    public static String gradeTermsKey(String grade) {
91	        return TERMS + "-" + grade;
92	    }
93	    /** The terms of the grade in force on the date: its own terms, or the sheet's terms when it has none of its own. */
94	    public int terms(String sheetId, String grade, LocalDate date) {
95	        String value = on(sheetId, gradeTermsKey(grade), date);
96	        return value.isEmpty() ? terms(sheetId, date) : Integer.parseInt(value);
97	    }
98	    /** The late percent in force on the date, with two decimals: what an overdue claim gains per full 30 days; 0.00 when none is. */
99	    public BigDecimal latePct(String sheetId, LocalDate date) {
100	        String value = on(sheetId, LATE_PCT, date);
101	        return new BigDecimal(value.isEmpty() ? LATE_PCT_DEFAULT : value);
102	    }
103	    /** The policy date: the one set, or the sheet's today when it is blank. */
104	    public LocalDate policyDate(String sheetId) {
105	        String value = get(sheetId, POLICY_DATE);
106	        return value.isEmpty() ? sheets.today(sheetId) : LocalDate.parse(value);
107	    }
108	    /** The date from which opened claims are numbered within their period; null when it is off. */
109	    public LocalDate periodNumberingFrom(String sheetId) {
110	        String value = get(sheetId, PERIOD_NUMBERING_FROM);
111	        return value.isEmpty() ? null : LocalDate.parse(value);
112	    }
113	    /**
114	     * How the claim's live figures round: half up when it is dated before the policy date, half to even on or after it.
115	     * A correction rounds by the date of the claim it corrects.
116	     */
117	    public RoundingMode rounding(Claim claim) {
118	        LocalDate date = claim.date();
119	        if (claim.isCorrection() && claim.corrects() != null) {
120	            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
121	            if (corrected != null) {
122	                date = corrected.date();
123	            }
124	        }
125	        return date.isBefore(policyDate(claim.sheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
126	    }
127	    /** The claim's live due at the rate (a percent): its amount times the rate, rounded by {@link #rounding}, raised to the floor; null (no rate) stays null. */
128	    public BigDecimal live(Claim claim, BigDecimal rate) {
129	        return rate == null ? null
130	                : floored(claim, claim.amount().multiply(rate).movePointLeft(2).setScale(2, rounding(claim)));
131	    }
132	    /**
133	     * A claim's figure with its late charge added on top: an open (OPEN or PENDING) claim whose due-by (fixed when it was made) is
134	     * before {@code today} gains the late percent in force on the claim's date of the figure for every full 30 days it is overdue, rounded by {@link #rounding}.
135	     * The charge is never bound by a statement, so it follows the sheet's today; null (no figure) stays null.
136	     * A correction has no late charge, nor has a deferred claim (it is not overdue until the sheet's today reaches its date).
137	     */
138	    public BigDecimal withLate(Claim claim, BigDecimal figure, LocalDate today) {
139	        if (figure == null || !claim.status().isOpen() || claim.isCorrection() || claim.deferredOn(today)) {
140	            return figure;
141	        }
142	        LocalDate dueBy = claim.dueBy();
143	        if (!dueBy.isBefore(today)) {
144	            return figure;
145	        }
146	        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
147	        BigDecimal charge = figure.multiply(latePct(claim.sheetId(), claim.date())).multiply(BigDecimal.valueOf(periods))
148	                .movePointLeft(2).setScale(2, rounding(claim));
149	        return figure.add(charge);
150	    }
151	    /** The claim's live due raised to the floor in force on the claim's date; null (no due) stays null, and a correction's due has no floor. */
152	    public BigDecimal floored(Claim claim, BigDecimal due) {
153	        return due == null || claim.isCorrection() ? due : due.max(floor(claim.sheetId(), claim.date()));
154	    }
155	    /** The sheet's roles, by user name. */
156	    public List<Role> roles(String sheetId) {
157	        return jdbc.query("SELECT * FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
158	                (rs, n) -> new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role")), sheetId);
159	    }
160	    /** The user's role: clerk unless the sheet gave them another. */
161	    public String role(String sheetId, String user) {
162	        List<String> roles = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
163	                String.class, sheetId, user);
164	        return roles.isEmpty() ? CLERK : roles.get(0);
165	    }
166	    public void save(Role role) {
167	        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
168	                role.sheetId(), role.user(), role.role());
169	    }
170	}
