172	public class ValidateSettings {
173	    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");
174	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?");
175	    // The amounts are kept with two decimals. A blank floor leaves the floor as it is; a blank clerk limit is
176	    // no limit, unless a floor, terms, late percent or policy date are saved with it, when the clerk limit is left as it is (and null
177	    // leaves it as it is too). Anything else that is not an amount of 0.00 or more with up to two decimals is
178	    // refused. Blank terms are left as they are; otherwise they must be a whole number of days, 0 or more.
179	    // A blank late percent is left as it is; otherwise it must be a percent of 0.00 or more, with up to two decimals.
180	    // A missing policy date is left as it is; a blank one is none (the sheet's today is); otherwise it must be a yyyy-MM-dd date.
181	    // A grade's own terms are like the terms: blank is left as it is, otherwise a whole number of days, 0 or more,
182	    // and only a grade (A, B or C) may have them.
183	    // The period numbering from-date is the same: missing is left as it is, blank is off, otherwise a yyyy-MM-dd date.
184	    // The cap is missing: left as it is, blank: none, otherwise an amount of 0.00 or more with up to two decimals.
185	    // A from-date, given by setting key, is blank (the sheet's today) or a yyyy-MM-dd date, and only a dated setting has one.
186	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingsRequest body,
187	            Out<SheetSettings> settingsOut) throws InvalidSettingException {
188	        String floor = body == null || body.floor() == null ? "" : body.floor().trim();
189	        if (!floor.isEmpty() && !AMOUNT.matcher(floor).matches()) {
190	            throw new InvalidSettingException("The floor must be an amount of 0.00 or more, with up to two decimals.");
191	        }
192	        String typed = body == null || body.clerkLimit() == null ? null : body.clerkLimit().trim();
193	        if (typed != null && !typed.isEmpty() && !AMOUNT.matcher(typed).matches()) {
194	            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more, with up to two decimals.");
195	        }
196	        String terms = body == null || body.terms() == null ? "" : body.terms().trim();
197	        if (!terms.isEmpty() && !DAYS.matcher(terms).matches()) {
198	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
199	        }
200	        SortedMap<String, String> gradeTerms = new TreeMap<>();
201	        if (body != null && body.gradeTerms() != null) {
202	            for (Map.Entry<String, String> entry : body.gradeTerms().entrySet()) {
203	                String grade = entry.getKey() == null ? "" : entry.getKey().trim();
204	                String days = entry.getValue() == null ? "" : entry.getValue().trim();
205	                if (days.isEmpty()) {
206	                    continue;
207	                }
208	                if (!Settings.GRADES.contains(grade)) {
209	                    throw new InvalidSettingException("Terms can be set only for grade A, B or C.");
210	                }
211	                if (!DAYS.matcher(days).matches()) {
212	                    throw new InvalidSettingException("The terms of grade " + grade + " must be a whole number of days, 0 or more.");
213	                }
214	                gradeTerms.put(grade, Integer.toString(Integer.parseInt(days)));
215	            }
216	        }
217	        String latePct = body == null || body.latePct() == null ? "" : body.latePct().trim();
218	        if (!latePct.isEmpty() && !AMOUNT.matcher(latePct).matches()) {
219	            throw new InvalidSettingException("The late percent must be a percent of 0.00 or more, with up to two decimals.");
220	        }
221	        String policyDate = body == null || body.policyDate() == null ? null : body.policyDate().trim();
222	        if (policyDate != null && !policyDate.isEmpty()) {
223	            try {
224	                policyDate = LocalDate.parse(policyDate).toString();
225	            } catch (DateTimeParseException e) {
226	                throw new InvalidSettingException("The policy date must be a date (yyyy-mm-dd).");
227	            }
228	        }
229	        String numberingFrom = body == null || body.periodNumberingFrom() == null ? null : body.periodNumberingFrom().trim();
230	        if (numberingFrom != null && !numberingFrom.isEmpty()) {
231	            try {
232	                numberingFrom = LocalDate.parse(numberingFrom).toString();
233	            } catch (DateTimeParseException e) {
234	                throw new InvalidSettingException("The period numbering from-date must be a date (yyyy-mm-dd).");
235	            }
236	        }
237	        String cap = body == null || body.cap() == null ? null : body.cap().trim();
238	        if (cap != null && !cap.isEmpty()) {
239	            if (!AMOUNT.matcher(cap).matches()) {
240	                throw new InvalidSettingException("The cap must be an amount of 0.00 or more, with up to two decimals.");
241	            }
242	            cap = twoDecimals(cap);
243	        }
244	        Map<String, LocalDate> from = new java.util.HashMap<>();
245	        if (body != null && body.from() != null) {
246	            for (Map.Entry<String, String> entry : body.from().entrySet()) {
247	                String key = entry.getKey() == null ? "" : entry.getKey().trim();
248	                String date = entry.getValue() == null ? "" : entry.getValue().trim();
249	                if (date.isEmpty()) {
250	                    continue;
251	                }
252	                if (!Settings.DATED.contains(key)) {
253	                    throw new InvalidSettingException("Only a setting that carries a figure has a from-date.");
254	                }
255	                try {
256	                    from.put(key, LocalDate.parse(date));
257	                } catch (DateTimeParseException e) {
258	                    throw new InvalidSettingException("The from-date must be a date (yyyy-mm-dd).");
259	                }
260	            }
261	        }
262	        boolean others = !floor.isEmpty() || !terms.isEmpty() || !gradeTerms.isEmpty() || !latePct.isEmpty() || policyDate != null
263	                || numberingFrom != null || cap != null;
264	        if (typed == null && !others) {
265	            typed = "";
266	        }
267	        String limit = typed == null || (typed.isEmpty() && others) ? null
268	                : typed.isEmpty() ? "" : twoDecimals(typed);
269	        settingsOut.set(new SheetSettings(sheetId.trim(), limit, floor.isEmpty() ? null : twoDecimals(floor),
270	                terms.isEmpty() ? null : Integer.toString(Integer.parseInt(terms)),
271	                latePct.isEmpty() ? null : twoDecimals(latePct), policyDate, numberingFrom, cap, gradeTerms, from));
272	    }
273	    private static String twoDecimals(String amount) {
274	        return new BigDecimal(amount).setScale(2, RoundingMode.UNNECESSARY).toPlainString();
275	    }
