292	public class ValidateClaim {
293	    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
294	    private static final Pattern NUMBER = Pattern.compile("\\d{1,18}|.{1,280}-\\d{1,18}");
295	    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
296	            .withResolverStyle(ResolverStyle.STRICT);
297	    // The amount is required; a blank date takes the sheet's today (filled in when stored); the note may be empty.
298	    // A negative amount is a correction and must name the number it corrects; no other claim may name one.
299	    // Whether that number is a SETTLED claim of the same person is checked once the person is loaded.
300	    public void validate(@RequestBody ClaimRequest body, Out<ClaimInput> input) throws InvalidClaimException {
301	        input.set(parse(body));
302	    }
303	    /** The claim form's rules on a typed body; shared with the paste box, which checks every line by them. */
304	    static ClaimInput parse(ClaimRequest body) throws InvalidClaimException {
305	        String amount = body == null || body.amount() == null ? "" : body.amount().trim();
306	        String date = body == null || body.date() == null ? "" : body.date().trim();
307	        String note = body == null || body.note() == null ? "" : body.note().trim();
308	        String corrects = body == null || body.corrects() == null ? "" : body.corrects().trim();
309	        if (!AMOUNT.matcher(amount).matches()) {
310	            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
311	        }
312	        BigDecimal value = new BigDecimal(amount).setScale(2);
313	        if (value.signum() < 0 && corrects.isEmpty()) {
314	            throw new InvalidClaimException("A negative amount is a correction: name the number of the settled claim it corrects.");
315	        }
316	        if (value.signum() >= 0 && !corrects.isEmpty()) {
317	            throw new InvalidClaimException("Only a claim with a negative amount corrects another.");
318	        }
319	        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
320	            throw new InvalidClaimException("Not a claim number: " + corrects);
321	        }
322	        LocalDate parsed = null;
323	        if (!date.isEmpty()) {
324	            try {
325	                parsed = LocalDate.parse(date, ISO);
326	            } catch (DateTimeParseException e) {
327	                throw new InvalidClaimException("Not a date (yyyy-mm-dd): " + date);
328	            }
329	        }
330	        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects);
331	    }
332	}
