539	public class ValidatePaste {
540	    // Every line is checked before any is added: name,amount,date,note — the name a person on the sheet (ignoring
541	    // case and surrounding spaces), the rest by the claim form's rules (a blank date is the sheet's today, the note
542	    // may hold commas or be absent). Blank lines are skipped; a paste with no line is refused.
543	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PasteRequest body, People people,
544	            Sheets sheets, Periods periods, Out<PastedLines> out)
545	            throws InvalidClaimException, ClaimInClosedPeriodException, ClaimAfterRetirementException {
546	        String sheet = sheetId.trim();
547	        String text = body == null || body.text() == null ? "" : body.text();
548	        List<PastedLine> lines = new ArrayList<>();
549	        int n = 0;
550	        for (String line : text.split("\\r?\\n")) {
551	            n++;
552	            if (line.isBlank()) {
553	                continue;
554	            }
555	            String[] fields = line.split(",", 4);
556	            if (fields.length < 2) {
557	                throw new InvalidClaimException("Line " + n + ": type name,amount,date,note.");
558	            }
559	            String name = fields[0].trim();
560	            Person person = name.isEmpty() ? null : people.findByName(sheet, name);
561	            if (person == null) {
562	                throw new InvalidClaimException("Line " + n + ": no person " + name + " on this sheet.");
563	            }
564	            ClaimInput input;
565	            try {
566	                input = ValidateClaim.parse(new ClaimRequest(fields[1], fields.length > 2 ? fields[2] : "",
567	                        fields.length > 3 ? fields[3] : "", ""));
568	            } catch (InvalidClaimException e) {
569	                throw new InvalidClaimException("Line " + n + ": " + e.getMessage());
570	            }
571	            LocalDate date = input.date() != null ? input.date() : sheets.today(sheet);
572	            Period closed = periods.closedOn(sheet, date);
573	            if (closed != null) {
574	                throw new ClaimInClosedPeriodException("Line " + n + ": the period " + closed.name()
575	                        + " is closed: no claim dated " + date + " can be added.");
576	            }
577	            RefuseRetiredInput.check(person, date);
578	            lines.add(new PastedLine(person, input));
579	        }
580	        if (lines.isEmpty()) {
581	            throw new InvalidClaimException("Paste at least one line of name,amount,date,note.");
582	        }
583	        out.set(new PastedLines(lines));
584	    }
