96	    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
97	            .withResolverStyle(ResolverStyle.STRICT);
98	    // A period needs a name not already used on the sheet, and a from and to date (yyyy-mm-dd), the
99	    // to-date on or after the from-date, sharing no day with another of the sheet's periods.
100	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PeriodRequest body, Periods periods,
101	            Out<Period> periodOut) throws InvalidPeriodException {
102	        String name = body == null || body.name() == null ? "" : body.name().trim();
103	        if (name.isEmpty()) {
104	            throw new InvalidPeriodException("A period needs a name.");
105	        }
106	        LocalDate from = date(body.from(), "from");
107	        LocalDate to = date(body.to(), "to");
108	        if (to.isBefore(from)) {
109	            throw new InvalidPeriodException("The to-date must be on or after the from-date.");
110	        }
111	        Period period = new Period(sheetId.trim(), name, from, to);
112	        for (Period other : periods.list(period.sheetId())) {
113	            if (other.name().equals(name)) {
114	                throw new InvalidPeriodException("There is already a period named " + name + ".");
115	            }
116	            if (other.overlaps(period)) {
117	                throw new InvalidPeriodException("The period overlaps " + other.name() + ".");
118	            }
119	        }
120	        periodOut.set(period);
121	    }
