123	        try {
124	            return LocalDate.parse(typed == null ? "" : typed.trim(), ISO);
125	        } catch (DateTimeParseException e) {
126	            throw new InvalidPeriodException("The " + which + "-date must be a date (yyyy-mm-dd).");
127	        }
128	    }
