258	public class TakeStatement {
259	    // Records the person's due-total now (a deferred claim counts in none and is left unbound) (held to the sheet's cap) and binds each of their counting claims (their open claims within a hold and not bound do not count) to its figure now;
260	    // the rest of their claims are left unbound. The late charge is never bound: the due-total includes it,
261	    // but each claim is bound to the figure under it.
262	    public void take(@Val Person person, Claims claims, Rates rates, Settings settings, Sheets sheets, Statements statements,
263	            Out<Statement> statementOut) {
264	        statements.lock(person.id());
265	        LocalDate today = sheets.today(person.sheetId());
266	        Map<Long, BigDecimal> figures = new LinkedHashMap<>();
267	        BigDecimal total = BigDecimal.ZERO.setScale(2);
268	        for (Claim claim : claims.list(person.sheetId())) {
269	            if (claim.personId() == person.id()
270	                    && (claim.status() == ClaimStatus.SETTLED || (claim.status().isOpen() && Rollup.counts(claim, person, today)))) {
271	                BigDecimal figure = figure(claim, person, rates, settings);
272	                figures.put(claim.id(), figure);
273	                BigDecimal due = claim.settledDue() != null ? figure : settings.withLate(claim, figure, today);
274	                if (due != null) {
275	                    total = total.add(due);
276	                }
277	            }
278	        }
279	        // With no rate today and no figure, the due-total is n/a.
280	        boolean none = rates.on(person.sheetId(), person.gradeOn(today), today) == null
281	                && figures.values().stream().allMatch(Objects::isNull);
282	        claims.bind(person.sheetId(), person.id(), figures);
283	        Statement statement = new Statement(person.sheetId(), person.id(),
284	                none ? "n/a" : settings.capped(person.sheetId(), total).toPlainString(),
285	                figures.size(), today);
286	        statements.add(statement);
287	        statementOut.set(statement);
288	    }
289	    /**
290	     * The claim's figure now (null when it has none): a settled claim's frozen due, otherwise the figure the
291	     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, rounded by the policy date, raised to the floor.
292	     */
293	    private static BigDecimal figure(Claim claim, Person person, Rates rates, Settings settings) {
294	        if (claim.settledDue() != null) {
295	            return claim.settledDue();
296	        }
297	        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
298	            return claim.statedDue();
299	        }
300	        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
301	        return settings.live(claim, rate);
302	    }
303	}
