595	/**
596	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
597	 * so tests can assert side-effects by reading that file — the second test-assertion channel
598	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
599	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
600	 *
601	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
602	 * SYNC) so a test reads the record immediately.
603	 */
604	@Service
605	public class Audit {
606	    private final Path file;
607	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
608	        this.file = Path.of(path);
609	    }
610	    /** Append one audit record. Tests assert the exact line(s) in the file. */
611	    public synchronized void record(String entry) {
612	        try {
613	            Path parent = file.toAbsolutePath().getParent();
614	            if (parent != null) {
615	                Files.createDirectories(parent);
616	            }
617	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
618	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
619	        } catch (IOException e) {
620	            throw new UncheckedIOException(e);
621	        }
622	    }
623	    /** The signed-in user a write names in its X-User header ("" when it names none). */
624	    public static String user(ServerHttpConnection connection) {
625	        HttpHeader header = connection.getRequest().getHeaders().getHeader("X-User");
626	        return header == null ? "" : header.getValue();
627	    }
628	    /** One record: the event, then sheet=<id> and by=<user>, then the fields, separated by single spaces. */
629	    public static String line(String event, String sheetId, String user, String... fields) {
630	        StringBuilder line = new StringBuilder(event).append(" sheet=").append(sheetId)
631	                .append(" by=").append(user == null ? "" : user.trim());
632	        for (String field : fields) {
633	            line.append(' ').append(field);
634	        }
635	        return line.toString();
636	    }
637	    /** Remove the audit file. */
638	    public synchronized void clear() {
639	        try {
640	            Files.deleteIfExists(file);
641	        } catch (IOException e) {
642	            throw new UncheckedIOException(e);
643	        }
644	    }
645	}
