import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { claimsKey } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { useUser } from '../session/useUser';
import { statementsKey, statementsQuery } from './statementsQuery';
import type { Statements } from './statementsQuery';

/**
 * A person's statements and the button that takes one: it records their due-total now and binds each of
 * their counting claims to its figure now, until their next statement.
 */
function PersonStatement({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [error, setError] = useState('');
  const once = useSubmitOnce();
  const shown = (useQuery(statementsQuery(sheetId)).data ?? []).find((s) => s.personId === personId);
  const take = useMutation({
    mutationFn: () =>
      postJson<Statements>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/statement`, {}, user),
    // The claims are re-read first, so the count moves on only once the bound figures show.
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      await queryClient.invalidateQueries({ queryKey: statementsKey(sheetId) });
    },
    onError: () => setError('The statement could not be taken.'),
  });

  return (
    <td>
      <span data-testid="person-statement-count">{shown?.count ?? 0}</span>{' '}
      <span data-testid="person-stated-total">{shown?.dueTotal ?? ''}</span>{' '}
      <span data-testid="person-statement-date">{shown?.date ?? ''}</span>{' '}
      <button
        type="button"
        data-testid="person-statement"
        disabled={take.isPending}
        onClick={() => {
          setError('');
          once(() => take.mutateAsync());
        }}
      >
        Statement
      </button>
      {error && <span data-testid="person-error">{error}</span>}
    </td>
  );
}

/** Whether the person's last statement bound the claim to its figure. */
function ClaimStated({ claim }: { sheetId: string; claim: Claim }) {
  return <td data-testid="claim-stated">{claim.stated ? 'yes' : 'no'}</td>;
}

export const contributions = [
  PersonHeaders.fill({ order: 17, Component: () => <th>Statements</th> }),
  PersonCells.fill({ order: 17, Component: PersonStatement }),
  ClaimCells.fill({ order: 15, Component: ClaimStated }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson, RefusedError } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useUser } from '../session/useUser';
import { claimsKey } from './claimsQuery';
import { useClaimError } from './useClaimError';
import type { Claim, ClaimStatus } from './claimsQuery';

type Decision = 'approve' | 'reject';

const ACTIONS: Array<{ action: string; to: ClaimStatus; label: string; decision?: Decision }> = [
  { action: 'open', to: 'OPEN', label: 'Open' },
  { action: 'settle', to: 'SETTLED', label: 'Settle' },
  { action: 'void', to: 'VOID', label: 'Void' },
  { action: 'approve', to: 'SETTLED', label: 'Approve', decision: 'approve' },
];

/**
 * A claim's status and the buttons that change it. Every button is offered; the server refuses a
 * change the status does not allow, a settle by the user who opened the claim, a clerk's settle of a claim
 * whose due is above the sheet's clerk limit, or any change to a claim dated in a closed period, and the refusal
 * shows on the claim until its next action. A clerk's settle above the clerk limit makes the claim PENDING: a
 * steward other than its opener approves it (SETTLED) or rejects it with a reason (back to OPEN). A steward can
 * re-settle a SETTLED claim, freezing it again at today's figure; the server refuses anyone else or any other status.
 */
function ClaimStatusCell({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [error, setError] = useClaimError(claim.id);
  const [reason, setReason] = useState('');
  const once = useSubmitOnce();
  const change = useMutation({
    mutationFn: ({ to, decision, reason }: { to: ClaimStatus; decision?: Decision; reason?: string }) =>
      putJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/status/${to}`,
        { action: decision, reason },
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
    onError: (e, { to, decision, reason }) =>
      setError(
        e instanceof RefusedError
          ? e.message
          : (decision !== undefined) !== (claim.status === 'PENDING') && to !== 'VOID'
            ? decision !== undefined
              ? `Only a PENDING claim can be ${decision === 'approve' ? 'approved' : 'rejected'}.`
              : 'A PENDING claim is approved or rejected by a steward, or voided.'
            : to === 'SETTLED' && claim.openedBy === user
              ? `The user who opened a claim cannot ${decision === 'approve' ? 'approve' : 'settle'} it.`
              : decision === 'reject' && !reason?.trim()
                ? 'Give a reason to reject the claim.'
                : decision !== undefined
                  ? 'Only a steward can approve or reject a pending claim.'
                  : `A ${claim.status} claim cannot become ${to}.`,
      ),
  });

  const resettle = useMutation({
    mutationFn: () =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/resettle`, {}, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
    onError: (e) =>
      setError(e instanceof RefusedError ? e.message : 'The claim could not be re-settled.'),
  });

  return (
    <td>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, to, label, decision }) => (
        <button
          key={action}
          type="button"
          data-testid={`claim-${action}`}
          disabled={change.isPending}
          onClick={() => {
            setError('');
            once(() => change.mutateAsync({ to, decision }));
          }}
        >
          {label}
        </button>
      ))}
      <button
        type="button"
        data-testid="claim-resettle"
        disabled={resettle.isPending}
        onClick={() => {
          setError('');
          once(() => resettle.mutateAsync());
        }}
      >
        Re-settle
      </button>
      <input
        data-testid="claim-reject-reason"
        placeholder="Reason"
        value={reason}
        onChange={(e) => {
          setReason(e.target.value);
          setError('');
        }}
      />
      <button
        type="button"
        data-testid="claim-reject"
        disabled={change.isPending}
        onClick={() => {
          setError('');
          once(() => change.mutateAsync({ to: 'OPEN', decision: 'reject', reason }).then(() => setReason('')));
        }}
      >
        Reject
      </button>
      {error && <span data-testid="claim-error">{error}</span>}
    </td>
  );
}

export const contribution = ClaimCells.fill({ order: 20, Component: ClaimStatusCell });
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from '../people/peopleQuery';
import { claimsKey, claimsQuery } from './claimsQuery';
import type { Claim } from './claimsQuery';
import { useSelectedClaims } from './useSelectedClaims';

type Result = { settled: number; refused: number };

/**
 * Settles every ticked claim as the signed-in user, one at a time in list order (people in their list
 * order, newest claim first within a person), by the same rules as settling one claim. A claim that
 * goes to PENDING counts as settled; a claim the server refuses to settle is left as it is and counted
 * as refused.
 */
function BulkSettle({ user, sheetId }: { user: string; sheetId: string }) {
  const queryClient = useQueryClient();
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const [selected, setSelected] = useSelectedClaims();
  const [result, setResult] = useState<Result | undefined>();
  const once = useSubmitOnce();

  const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.includes(c.id)));

  const settle = useMutation({
    mutationFn: async (targets: Claim[]): Promise<Result> => {
      let settled = 0;
      for (const c of targets) {
        try {
          await putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/status/SETTLED`, {}, user);
          settled++;
        } catch {
          // refused: left as it is
        }
      }
      return { settled, refused: targets.length - settled };
    },
    onSuccess: async (r) => {
      setSelected([]);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      setResult(r);
    },
  });

  return (
    <section data-testid="bulk-settle-panel">
      <button
        type="button"
        data-testid="bulk-settle"
        disabled={settle.isPending}
        onClick={() => {
          setResult(undefined);
          once(() => settle.mutateAsync(ordered));
        }}
      >
        Settle selected
      </button>
      {result && (
        <>
          {' '}
          Settled <span data-testid="bulk-settled">{result.settled}</span>, refused{' '}
          <span data-testid="bulk-settle-refused">{result.refused}</span>
        </>
      )}
    </section>
  );
}

export const contribution = SheetPanel.fill({
  order: 22,
  Component: ({ user, sheetId }) => <BulkSettle key={sheetId} user={user} sheetId={sheetId} />,
});
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from '../people/peopleQuery';
import { claimsKey, claimsQuery } from './claimsQuery';
import type { Claim } from './claimsQuery';
import { useSelectedClaims } from './useSelectedClaims';

type Result = { opened: number; refused: number };

/**
 * Opens every ticked claim, one at a time in list order (people in their list order, newest claim
 * first within a person), so each is numbered in that order. A claim the server refuses to open is
 * left as it is and counted as refused.
 */
function BulkOpen({ user, sheetId }: { user: string; sheetId: string }) {
  const queryClient = useQueryClient();
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const [selected, setSelected] = useSelectedClaims();
  const [result, setResult] = useState<Result | undefined>();
  const once = useSubmitOnce();

  const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.includes(c.id)));

  const open = useMutation({
    mutationFn: async (targets: Claim[]): Promise<Result> => {
      let opened = 0;
      for (const c of targets) {
        try {
          await putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${c.id}/status/OPEN`, {}, user);
          opened++;
        } catch {
          // refused: left as it is
        }
      }
      return { opened, refused: targets.length - opened };
    },
    onSuccess: async (r) => {
      setSelected([]);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      setResult(r);
    },
  });

  return (
    <section data-testid="bulk-open-panel">
      <button
        type="button"
        data-testid="bulk-open"
        disabled={open.isPending}
        onClick={() => {
          setResult(undefined);
          once(() => open.mutateAsync(ordered));
        }}
      >
        Open selected
      </button>
      {result && (
        <>
          {' '}
          Opened <span data-testid="bulk-opened">{result.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{result.refused}</span>
        </>
      )}
    </section>
  );
}

export const contribution = SheetPanel.fill({
  order: 21,
  Component: ({ user, sheetId }) => <BulkOpen key={sheetId} user={user} sheetId={sheetId} />,
});
import { useQuery } from '@tanstack/react-query';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import { personDue, ratesQuery } from '../rates/ratesQuery';
import { useCap, useFloor, useLate } from '../settings/settingsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { gradeOn, peopleQuery } from './peopleQuery';

/** A CSV value: wrapped in double quotes, with inner quotes doubled, when it holds a comma, a quote or a line break. */
function csvValue(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

/** Downloads the people as CSV, in list order and retired people included, with the figures the screen shows. */
function ExportPeople({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);

  const exportCsv = () => {
    const lines = [
      'name,grade,retired-from,due-total',
      ...people.map((p) =>
        [p.name, gradeOn(p, today) ?? p.grade, p.retiredFrom ?? '', personDue(p, people, claims, rates, today, floor, late, cap)]
          .map(csvValue)
          .join(','),
      ),
    ];
    const url = URL.createObjectURL(new Blob([lines.map((l) => l + '\n').join('')], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = 'people.csv';
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={exportCsv}>
        Export people (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanel.fill({ order: 11, Component: ExportPeople });
import { useQuery } from '@tanstack/react-query';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from './peopleQuery';
import { PersonForm } from './PersonForm';
import { useEditingPerson } from './useEditingPerson';
import { useShowRetired } from './useShowRetired';

function People({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId));
  const [, setEditingId] = useEditingPerson();
  const [showRetired, setShowRetired] = useShowRetired();
  // Retired people have no row at all unless "show retired" is on; their claims still count in every total.
  const listed = (people.data ?? []).filter((p) => showRetired || !p.retiredFrom);

  return (
    <section data-testid="people">
      <h3>People</h3>
      <PersonForm sheetId={sheetId} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>
      {people.isError && <p data-testid="people-load-error">Could not load the people.</p>}
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <PersonHeaders.Slot sheetId={sheetId} />
            <th />
          </tr>
        </thead>
        <tbody>
          {listed.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <PersonCells.Slot sheetId={sheetId} personId={p.id} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditingId(p.id)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

// Keyed by sheet, so a typed name or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 10,
  Component: ({ sheetId }) => <People key={sheetId} sheetId={sheetId} />,
});
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { claimsQuery } from './claimsQuery';
import { ClaimForm } from './ClaimForm';

/** A person's claims, newest first, with the form they are added and edited through. */
function PersonClaims({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = (useQuery(claimsQuery(sheetId)).data ?? []).filter((c) => c.personId === personId);
  const [editingId, setEditingId] = useState<number | undefined>();
  const editing = claims.find((c) => c.id === editingId);

  return (
    <td data-testid="person-claims">
      <table>
        <tbody>
          {claims.map((c) => (
            <tr key={c.id} data-testid={`claim-row-${c.id}`}>
